\begin{definition}[Reflection in a half-space]
\label{def:reflection-half-space}


\dcref{ch2:2.2.4-def-2}
\group{Green's Functions}


For $x=(x_1,\ldots,x_{n-1},x_n)\in\R^n_+$, define
$$\overline x=(x_1,\ldots,x_{n-1},-x_n).$$
\end{definition}

